-- Biology Ch1 (The Cell) — Batch 4 of 4: Microbial genetics + viruses + prions and viroids (AAMC 2A "Prokaryotes and Viruses (BIO)")
-- 25 questions, all confidence >=4 (cited to OpenStax Microbiology (prokaryote structure/wall/Gram/growth) + Biology 2e (domains)).
-- Difficulty 7 easy / 10 medium / 8 hard (every hard passes the two-axis Hard-Tier gate); answer key A/B/C/D = 7/6/6/6; deduped internally + vs the live Batch 1-3+2.
-- section bio_biochem, discipline biology, foundation 2A. Re-runnable: subtopic-scoped DELETE. Run in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'The Cell' AND subtopic IN ('Prions and Viroids', 'Prokaryotic Genetics: Conjugation', 'Prokaryotic Genetics: Plasmids', 'Prokaryotic Genetics: Transduction', 'Prokaryotic Genetics: Transformation', 'Prokaryotic Genetics: Transposons', 'Viral Genomes and Replication Strategy', 'Viral Life Cycle: Lytic and Lysogenic', 'Virus Structure');

-- Q1 [Prions and Viroids · easy · Skill 1 · ans D] (g98)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prions and Viroids',
    $qt98$A neurologist purifies the infectious particle from the brain tissue of a patient with Creutzfeldt-Jakob disease. Assays show the particle contains a misfolded version of a host protein but reveal no detectable DNA or RNA. Based on these findings, the infectious agent is most likely composed of:$qt98$,
    $op98$[{"label":"A","text":"a short strand of circular RNA with no protein coat"},{"label":"B","text":"a nucleic acid genome enclosed within a protein capsid"},{"label":"C","text":"a small loop of double-stranded DNA separate from the chromosome"},{"label":"D","text":"a misfolded protein with no nucleic acid"}]$op98$::jsonb,
    'D',
    $ex98$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because a prion is an infectious agent made entirely of a misfolded protein and contains no nucleic acid at all. The text states that prions are "proteinaceous infectious particles" and that "proteins are acellular and do not contain DNA or RNA," and defines a prion as "a misfolded rogue form of a normal protein (PrPc)" that stimulates "other endogenous normal proteins to become misfolded." Because the purified particle has a misfolded protein but no detectable DNA or RNA, it fits the definition of a prion rather than any nucleic-acid-based agent. (Choice A) A short strand of circular RNA with no protein coat describes a viroid: "Viroids consist only of a short strand of circular RNA," but the particle here contains protein and no RNA, so this is wrong. (Choice B) A nucleic acid genome enclosed within a protein capsid describes a virus, yet the assay found no DNA or RNA, so the agent cannot be a virus. (Choice C) A small loop of double-stranded DNA separate from the chromosome describes a plasmid, which is DNA, contradicting the absence of detectable nucleic acid. (Choice D) A misfolded protein with no nucleic acid matches the prion exactly, consistent with the finding of a misfolded protein and no DNA or RNA. This is a Knowledge of Scientific Concepts and Principles question because you must recall that a prion is an infectious misfolded protein that contains no nucleic acid.$ex98$,
    'easy', '2B', $cc98$Prokaryotes and Viruses (BIO)$cc98$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a98A$Confusing a prion with a viroid (the other acellular plant agent), substituting circular RNA for protein$a98A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a98B$Treating the prion as if it were a tiny virus with a nucleic-acid genome in a capsid, ignoring the absence of DNA/RNA$a98B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a98C$Confusing the prion with a plasmid (extrachromosomal circular DNA), substituting DNA for the protein$a98C$ FROM q;

-- Q2 [Prions and Viroids · medium · Skill 2 · ans B] (g100)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prions and Viroids',
    $qt100$A self-propagating agent converts a normally alpha-helix-rich host protein into a beta-sheet-rich conformation, and the altered form then templates the same conformational change onto additional copies of that protein; the agent contains no DNA or RNA. A researcher incubates a purified sample of this agent with a nuclease that degrades nucleic acids and then assays whether the treated sample can still seed conversion of host protein. The treated agent most likely retains its ability to propagate because$qt100$,
    $op100$[{"label":"A","text":"the nuclease cannot reach the agent's genome, which is shielded inside a protein capsid that protects its DNA or RNA"},{"label":"B","text":"the agent is composed only of protein, so it contains no nucleic acid for the nuclease to degrade"},{"label":"C","text":"the nuclease degrades only the agent's short circular RNA, leaving an intact protein replication template behind"},{"label":"D","text":"removing nucleic acid from the agent accelerates the conformational templating, increasing its rate of propagation"}]$op100$::jsonb,
    'B',
    $ex100$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because the agent described is a prion, an infectious particle made entirely of protein that carries no nucleic acid, so a nuclease has no substrate to act on and propagation is unaffected. The text states that "Prions are infectious proteinaceous particles that are not viruses and do not contain nucleic acid," and that the normal protein "folds into mostly alpha helices" whereas "The rogue protein, on the other hand, folds predominantly into beta-pleated sheets and is resistant to proteolysis. In addition, PrPSc can induce PrPC to become misfolded and produce more rogue protein" (lines 49971-49977). Because the template that drives propagation is the beta-sheet protein conformation itself rather than any DNA or RNA, an enzyme that cuts nucleic acids leaves the agent's mechanism of self-replication intact. (Choice A) is wrong because prions have no genome at all; they are acellular protein particles that "do not contain nucleic acid," so there is no capsid-shielded DNA or RNA. (Choice B) is correct because prion propagation depends solely on a protein conformational template, and a nuclease degrades only nucleic acids, of which the agent has none. (Choice C) describes a viroid, which "consist[s] only of a short strand of circular RNA capable of self-replication" (line 10925) and would in fact be inactivated by a nuclease, so it misidentifies the agent. (Choice D) is wrong because the nucleic-acid-degrading enzyme acts on a molecule the prion does not possess, so it can neither slow nor speed propagation; there is no mechanism by which removing absent nucleic acid would enhance protein templating. This is a Scientific Reasoning and Problem Solving question because you must apply the defining molecular property of the agent (protein-only composition) to predict the outcome of an experimental treatment that targets a different class of molecule.$ex100$,
    'medium', '2B', $cc100$Prokaryotes and Viruses (BIO)$cc100$, 'biology', 2, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a100A$Treats the prion as a virus with a nucleic-acid genome enclosed in a protective protein capsid, so the nuclease is imagined to be blocked rather than substrate-less.$a100A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a100C$Imports the true definition of a viroid (short circular RNA) and misapplies it to the protein-only agent, so the nuclease is thought to destroy an RNA the prion does not have.$a100C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a100D$Reverses the expected null result into an enhancement, inventing a stimulatory effect of nucleic-acid removal on protein conformational templating.$a100D$ FROM q;

-- Q3 [Prokaryotic Genetics: Conjugation · easy · Skill 1 · ans A] (g80)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Conjugation',
    $qt80$A donor strain of \(E.\ coli\) carrying the F (fertility) plasmid is mixed with an F− recipient strain, and microscopy shows the donor extending a single long protein appendage that contacts a recipient cell, retracts to pull the two cells together, and establishes the bridge through which a DNA strand then passes. Which donor-cell appendage is responsible for making this initial contact and drawing in the recipient?$qt80$,
    $op80$[{"label":"A","text":"The F pilus (sex pilus), encoded by the F plasmid"},{"label":"B","text":"The flagellum, the rotary appendage that propels the cell"},{"label":"C","text":"Fimbriae, the short bristle-like appendages that adhere to surfaces and host cells"},{"label":"D","text":"The capsule, the gelatinous outer layer surrounding the cell"}]$op80$::jsonb,
    'A',
    $ex80$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because conjugation is mediated by the F pilus, the F-plasmid-encoded appendage that contacts an F− recipient, retracts to bring the two cells together, and creates the cytoplasmic bridge for DNA transfer. The text states that "In conjugation, DNA is directly transferred from one prokaryote to another by means of a conjugation pilus, which brings the organisms into contact with one another," and that the genes for conjugating are "located on a bacterial plasmid called the F plasmid... and the conjugation pilus is called the F pilus" (lines 19494-19498). It further describes that "the F pilus of an F+ cell comes into contact with an F– cell and retracts, bringing the two cell envelopes into contact" (lines 19503-19504), exactly the situation in the stem. A separate passage confirms "A specific type of pilus, called the F pilus or sex pilus, is important in the transfer of DNA between bacterial cells" (line 4890). (Choice A) Correct: the F pilus is the F-plasmid-encoded appendage that physically mediates donor-to-recipient contact and DNA transfer in conjugation. (Choice B) The flagellum is the appendage responsible for motility, not gene transfer; the chapter on bacterial structure treats flagella as organs of "movement" alongside fimbriae and pili (line 4879), so it is an appendage but the wrong one. (Choice C) Fimbriae are structurally similar to pili but are "short bristle-like proteins" that "enable a cell to attach to surfaces and to other cells" for colonization, not the longer appendage that conducts conjugative DNA transfer (lines 4884-4885). (Choice D) The capsule is a protective gelatinous outer layer, not a filamentous appendage, and plays no role in extending toward or drawing in a recipient cell. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the F pilus, encoded by the F plasmid, is the surface appendage that mediates cell-to-cell contact during bacterial conjugation.$ex80$,
    'easy', '2B', $cc80$Prokaryotes and Viruses (BIO)$cc80$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a80B$Naming a different filamentous surface appendage (flagellum) that serves motility rather than DNA transfer$a80B$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a80C$Confusing the structurally similar adhesive appendage (fimbriae) with the conjugative pilus$a80C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a80D$Mistaking a non-appendage protective outer structure (capsule) for the transfer apparatus$a80D$ FROM q;

-- Q4 [Prokaryotic Genetics: Conjugation · medium · Skill 2 · ans B] (g81)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Conjugation',
    $qt81$A microbiologist mixes a pure culture of F+ Escherichia coli with a pure culture of F− E. coli that lacks the F plasmid and allows conjugation to run to completion. A student is asked to predict the donor/recipient status of a cell drawn from the original F− population after it has received DNA through the conjugation pilus. Which prediction is best supported?$qt81$,
    $op81$[{"label":"A","text":"It remains F− because the F plasmid is retained by the original donor and only a transient cytoplasmic bridge, not a copy of the plasmid, passes to the recipient."},{"label":"B","text":"It becomes F+ because it now carries a copy of the F plasmid and can build its own conjugation pilus, allowing it to act as a donor."},{"label":"C","text":"It becomes an Hfr cell because receiving the F plasmid causes that plasmid to integrate into the recipient's chromosome at a high frequency."},{"label":"D","text":"It becomes F− while the original donor becomes F− as well, because the single transferred plasmid is shared so that neither cell retains a complete copy."}]$op81$::jsonb,
    'B',
    $ex81$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because in a standard F+ × F− cross the recipient acquires a copy of the F plasmid and is thereby converted into an F+ donor. During typical conjugation, rolling circle replication in the F+ cell sends a single-stranded copy of the F plasmid across the cytoplasmic bridge; the text states that "a single-stranded copy of the F plasmid is transferred through the cytoplasmic bridge to the F− cell, which then synthesizes the complementary strand, making it double stranded. The F− cell now becomes an F+ cell capable of making its own conjugation pilus" (Microbiology, lines 19505–19508). Because the F plasmid encodes the genes for the F pilus, a cell that gains the plasmid gains donor status (lines 19499–19500). The original donor keeps its plasmid because rolling circle replication copies the plasmid rather than handing the only copy away, so transfer is unidirectional and both cells end up F+. (Choice A) is wrong because conjugation transfers an actual copy of the F plasmid, not merely a transient bridge — the recipient does not stay F−. (Choice B) is correct: the recipient becomes F+ and can itself make a pilus and act as a donor. (Choice C) reverses the route to an Hfr cell; an Hfr strain arises when the F plasmid integrates into the chromosome of a donor before transfer, not from a recipient simply receiving a free F plasmid, and that integration is not an automatic consequence of receipt. (Choice D) describes a nonexistent "sharing" outcome; rolling circle replication means the donor retains its plasmid while the recipient builds a complete double-stranded copy, so the donor does not lose F+ status. This is a Scientific Reasoning and Problem Solving question because you must apply the unidirectional, replicative mechanism of F-plasmid transfer to predict the recipient's mating type after the cross.$ex81$,
    'medium', '2B', $cc81$Prokaryotes and Viruses (BIO)$cc81$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a81A$Believes only a cytoplasmic bridge (not a plasmid copy) passes, so the recipient stays F−$a81A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a81C$Confuses receiving a free F plasmid with the integration event that creates an Hfr cell$a81C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a81D$Treats transfer as splitting one plasmid between cells rather than replicative copying, so both end up F−$a81D$ FROM q;

-- Q5 [Prokaryotic Genetics: Conjugation · medium · Skill 2 · ans C] (g82)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Conjugation',
    $qt82$A microbiologist places an F+ donor strain and an auxotrophic F− recipient strain in the two arms of a U-tube whose arms are separated by a fine filter: the filter lets the shared liquid medium pass freely between the arms but prevents any cell from crossing. No prototrophic recombinant recipients arise while the filter is in place, yet recombinants appear within hours once the filter is removed so the two populations can mingle. A student concludes that this outcome reflects a feature of conjugation that naked-DNA uptake would NOT share. Which explanation best accounts for the result?$qt82$,
    $op82$[{"label":"A","text":"The filter degrades any free DNA released into the shared medium, so genetic material from the donor is destroyed before it can reach the recipient in either arm."},{"label":"B","text":"The recipient is auxotrophic and therefore cannot import DNA across its envelope until it is supplied with the nutrients its donor partner secretes through the filter."},{"label":"C","text":"Conjugation requires a pilus to draw the cells together and transfer DNA through a direct cytoplasmic bridge, which the filter blocks, whereas transformation needs only free DNA that could diffuse across the filter."},{"label":"D","text":"The shared medium dilutes the donor's F plasmid below the concentration the recipient needs to take it up, so transfer resumes only once the cells are concentrated together."}]$op82$::jsonb,
    'C',
    $ex82$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because conjugation moves DNA only through a conjugation pilus that physically draws the two cells into direct contact, so a filter that blocks cell-to-cell contact while still letting the medium flow abolishes transfer—whereas transformation depends on free DNA that could diffuse across that same filter. The text states that "In conjugation, DNA is directly transferred from one prokaryote to another by means of a conjugation pilus, which brings the organisms into contact with one another" (lines 19494-19495), and that the F pilus "comes into contact with an F– cell and retracts, bringing the two cell envelopes into contact" before "a cytoplasmic bridge forms between the two cells" (lines 19503-19504). By contrast, transformation is defined as a process in which "naked DNA is taken up from the environment" (line 19372), a route that needs no cell contact and would not be stopped by a permeable filter. Because recombinants appear only when the filter is removed, the requirement being demonstrated is the direct physical contact unique to conjugation. (Choice A) The filter is described as a passive size barrier that lets the medium pass while excluding cells; nothing indicates it degrades DNA, and DNA-degrading nucleases are a property of the medium and competing cells, not of an inert filter. (Choice B) Auxotrophy means the recipient cannot synthesize a particular nutrient; it has no bearing on a cell's ability to import DNA, and conjugative transfer does not depend on the recipient first receiving secreted nutrients. (Choice C) is correct: the pilus-mediated cytoplasmic bridge demands direct contact that the filter prevents, while diffusible naked DNA would not be blocked. (Choice D) Conjugative transfer is initiated by pilus contact, not by reaching a threshold concentration of plasmid free in the medium; the F plasmid is passed cell-to-cell through the bridge, not taken up from solution. This is a Scientific Reasoning and Problem Solving question because you must apply the defining mechanism of conjugation to a novel experimental setup and predict why a physical barrier selectively abolishes one mode of gene transfer but not another.$ex82$,
    'medium', '2B', $cc82$Prokaryotes and Viruses (BIO)$cc82$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a82A$Attributing DNA destruction to an inert filter, conflating the barrier with nuclease activity$a82A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a82B$Invoking the recipient's auxotrophy (a real, mentioned trait) as a false mechanistic requirement for DNA uptake$a82B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a82D$Treating conjugation as concentration-dependent uptake of free plasmid from solution, confusing it with transformation$a82D$ FROM q;

-- Q6 [Prokaryotic Genetics: Conjugation · hard · Skill 2 · ans D] (g83)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Conjugation',
    $qt83$A microbiologist mates an Hfr strain of E. coli with an F− recipient population and interrupts the mating after only a few minutes. Among the surviving recipients, donor alleles that map nearest the F-integration site are recovered at high frequency, yet nearly every recipient that acquired those alleles is still F−. Which explanation BEST accounts for both the high-frequency transfer of those chromosomal alleles and the recipients remaining F−?$qt83$,
    $op83$[{"label":"A","text":"The Hfr donor carries its F sequences as a free cytoplasmic plasmid that is copied and transferred first, converting the recipient to F+, after which adjacent chromosomal genes follow."},{"label":"B","text":"A bacteriophage produced by the Hfr cell packages the donor chromosomal alleles and injects them into the recipient, a viral route that moves chromosomal DNA without transferring the F plasmid."},{"label":"C","text":"The Hfr recipient takes up the donor's chromosomal alleles as naked DNA released into the medium, a process that recombines genes efficiently but never delivers an intact F plasmid."},{"label":"D","text":"Because F is integrated into the donor chromosome, rolling-circle transfer begins within the chromosome and moves adjacent genes across first, while the rest of the integrated F plasmid would transfer last and rarely crosses before the transient contact breaks, leaving the recipient F−."}]$op83$::jsonb,
    'D',
    $ex83$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because integration of the F plasmid into the donor chromosome makes the chromosome behave like one enormous F plasmid: rolling-circle transfer initiates within the integrated element and pushes the adjacent chromosomal genes across first, so genes near the integration site move at high frequency, while the bulk of the F plasmid (which would complete the recipient's conversion to F+) is positioned to transfer last and is usually lost when the fragile mating bridge breaks. The text states that the F plasmid "occasionally integrates into the bacterial chromosome ... forming an Hfr cell," that "Hfr cells may also treat the bacterial chromosome like an enormous F plasmid," and that "contact between bacterial cells during conjugation is transient, so it is unusual for the entire chromosome to be transferred." It further notes that "Host chromosomal DNA near the integration site ... displaced by the unidirectional process of rolling circle replication, is more likely to be transferred ... than host genes farther away." Because the complete F sequence transfers last, recipients usually receive only early chromosomal genes and stay F−. (Choice A) describes an F+ donor, in which "typical conjugation in E. coli results in the transfer of the F-plasmid DNA only" and the recipient becomes F+ — the opposite of the Hfr outcome and it does not explain efficient chromosomal transfer. (Choice B) describes transduction, in which "a bacteriophage injects DNA," not conjugation; no phage is involved in an Hfr mating, so this is the wrong mechanism. (Choice C) describes transformation, the uptake of "naked DNA ... from the environment," which does not require the cell-to-cell contact and pilus that define the conjugative Hfr cross. (Choice D) correctly couples the integrated location of F to both the high-frequency, position-dependent transfer of chromosomal genes and the recipients' persistence as F−. This is a Scientific Reasoning and Problem Solving question because you must integrate the integrated location of the F plasmid, the unidirectional rolling-circle order of transfer, and the transient nature of the mating bridge to predict why early chromosomal genes move efficiently yet the recipient stays F−.$ex83$,
    'hard', '2B', $cc83$Prokaryotes and Viruses (BIO)$cc83$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a83A$Treats the Hfr donor as an F+ donor (free plasmid transferred first, recipient becomes F+) — the exact opposite of the Hfr outcome the stem describes.$a83A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a83B$Swaps in transduction (phage-mediated transfer of bacterial DNA) for conjugation.$a83B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a83C$Swaps in transformation (uptake of naked environmental DNA) for the contact-dependent conjugative cross.$a83C$ FROM q;

-- Q7 [Prokaryotic Genetics: Plasmids · easy · Skill 1 · ans A] (g76)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Plasmids',
    $qt76$A bacterium carries a gene for resistance to a particular antibiotic, and a researcher finds that this gene sits on a small circular DNA molecule that is physically separate from the cell's single main chromosome and replicates on its own. This separate, self-replicating DNA molecule is best identified as which structure?$qt76$,
    $op76$[{"label":"A","text":"A plasmid"},{"label":"B","text":"The nucleoid"},{"label":"C","text":"A transposon"},{"label":"D","text":"A competence factor"}]$op76$::jsonb,
    'A',
    $ex76$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because a plasmid is precisely a small, circular, extrachromosomal DNA molecule that replicates independently of the main chromosome and frequently carries non-essential genes such as those for antibiotic resistance. OpenStax Microbiology states that prokaryotic "extrachromosomal DNA is found in plasmids, which are small, circular, double-stranded DNA molecules" and that "Plasmids often carry genes that confer advantageous traits such as antibiotic resistance." Elsewhere the text describes "smaller loops of DNA called plasmids that may contain one or a few genes not essential for normal growth," confirming that plasmids are separate from the chromosome and dispensable. The scenario's description of a self-replicating, circular DNA molecule that is physically separate from the single main chromosome and carries an antibiotic-resistance gene matches the definition of a plasmid exactly. (Choice A) Correct: a plasmid is the small circular extrachromosomal element that replicates on its own and commonly encodes antibiotic resistance. (Choice B) The nucleoid is "the membrane-free region of the cytoplasm where the chromosomal DNA is localized"; it houses the main chromosome rather than being a separate small circular molecule, so it is not the resistance-bearing element. (Choice C) A transposon is a mobile genetic element that inserts into and excises from DNA; the text notes "transposons are mobile" elements, but a transposon is a movable segment, not a free-standing, self-replicating circular DNA molecule physically separate from the chromosome. (Choice D) A competence factor refers to the cellular machinery that lets a bacterium take up naked DNA from the environment during transformation; it is not a DNA molecule carrying a resistance gene. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition of a plasmid as a small, circular, self-replicating extrachromosomal DNA molecule that carries non-essential genes such as antibiotic resistance.$ex76$,
    'easy', '2B', $cc76$Prokaryotes and Viruses (BIO)$cc76$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a76B$Names the chromosome-housing region (nucleoid) instead of the separate extrachromosomal molecule$a76B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a76C$Confuses a mobile insertable element (transposon) with a free-standing self-replicating circular DNA$a76C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a76D$Substitutes the DNA-uptake machinery of transformation for the DNA molecule itself$a76D$ FROM q;

-- Q8 [Prokaryotic Genetics: Plasmids · medium · Skill 2 · ans B] (g77)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Plasmids',
    $qt77$During an outbreak investigation, a clinician notes that a single antibiotic-resistance trait spreads through a genetically mixed bacterial population within a few hours—far faster than the doubling time of the bacteria can account for—and the lab confirms the resistance gene sits on a conjugative plasmid rather than the chromosome. Which feature of plasmid-borne resistance best explains why it sweeps through the population so much faster than a resistance allele that arose by chromosomal mutation?$qt77$,
    $op77$[{"label":"A","text":"The plasmid is replicated by an RNA polymerase that copies it many more times per cell than the chromosomal origin allows, raising the resistance gene's copy number in each daughter cell."},{"label":"B","text":"The plasmid can be passed horizontally from cell to cell by conjugation, so resistance reaches new cells directly without requiring them to be descendants of a resistant cell."},{"label":"C","text":"The plasmid integrates into the recipient's chromosome upon entry, where it is shielded from nucleases and therefore inherited more reliably by all later generations."},{"label":"D","text":"The plasmid carries genes essential for the recipient's survival, so unresistant cells are rapidly outcompeted and die off, leaving only the resistant lineage."}]$op77$::jsonb,
    'B',
    $ex77$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is B because a conjugative plasmid moves the resistance gene horizontally—directly from a donor cell to neighboring recipient cells—so resistance can appear in cells that are not descendants of any resistant ancestor, decoupling the spread of the trait from the slow pace of vertical inheritance through cell division. A chromosomal mutation can only be passed vertically to a cell's own offspring, so its spread is capped by the population's doubling time; a plasmid-borne gene spreads both vertically and horizontally. The text notes that bacteria "can exchange these plasmids with other bacteria in a process known as horizontal gene transfer (HGT)" and that plasmids "often carry genes that confer advantageous traits such as antibiotic resistance." Crucially, in conjugation a single-stranded copy of the plasmid is transferred through a cytoplasmic bridge and "the F− cell now becomes an F+ cell capable of making its own conjugation pilus," so that "eventually, in a mixed bacterial population... all cells will become F+ cells"—a chain-reaction-style spread that needs no reproduction to reach new cells. (Choice A) Plasmid replication uses DNA polymerase (often rolling-circle replication), not an RNA polymerase, and although high copy number can exist, it does not move the gene between cells, which is what the rapid population-wide spread requires; this is a mechanism mix-up rather than the cause of rapid spread. (Choice B) is correct because horizontal conjugative transfer adds new resistant cells independent of reproduction. (Choice C) Plasmids are by definition extrachromosomal and need not integrate; integration (as in an Hfr cell) is the exception, and integration would actually make the gene behave more like a slowly inherited chromosomal allele, the opposite of what speeds spread. (Choice D) Plasmids carry traits that are advantageous but generally not essential for survival, and the trait spreads by transfer of the gene itself, not by selective death of cells that already lack it; this reverses the causal direction. This is a Scientific Reasoning and Problem Solving question because you must integrate how plasmids replicate and transfer with the difference between horizontal and vertical inheritance to predict why a conjugative trait outpaces a mutation-derived one.$ex77$,
    'medium', '2B', $cc77$Prokaryotes and Viruses (BIO)$cc77$, 'biology', 2, 105
  ) RETURNING id
)
