UNION ALL SELECT id, 'C', 'partial_truth', $a85C$Conjugation correctly transfers resistance genes cell-to-cell and resists DNase, but is excluded by the contact-blocking filter (510-tempting trap)$a85C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a85D$Confusing an intracellular mobile element (transposon) with an inter-cell horizontal gene transfer mechanism$a85D$ FROM q;

-- Q11 [Prokaryotic Genetics: Transformation · easy · Skill 1 · ans C] (g78)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Transformation',
    $qt78$A culture of antibiotic-sensitive bacteria is mixed with a sterile cell-free filtrate prepared from a lysed antibiotic-resistant strain; the filtrate contains naked DNA fragments but NO intact cells or viral particles. After incubation, a small number of the formerly sensitive cells grow on antibiotic-containing plates. Which process most directly accounts for the newly resistant cells?$qt78$,
    $op78$[{"label":"A","text":"Conjugation, in which the resistance plasmid is transferred from a donor cell to the recipient through a conjugation pilus"},{"label":"B","text":"Transduction, in which a bacteriophage packages the resistance gene and injects it into the recipient cell"},{"label":"C","text":"Transformation, in which the competent recipient cells take up the naked resistance DNA from the medium and recombine it into the genome"},{"label":"D","text":"Spontaneous mutation, in which exposure to the filtrate triggers random changes that independently generate a resistance allele"}]$op78$::jsonb,
    'C',
    $ex78$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because the resistant cells acquired the trait by taking up free DNA released into the medium, which is the definition of transformation. The textbook states that "In transformation, the prokaryote takes up naked DNA found in its environment and that is derived from other cells that have lysed on death and released their contents, including their genome, into the environment" (openstax-microbiology.txt, lines 19400-19405). The scenario provides exactly this: a cell-free filtrate of lysed resistant cells containing only naked DNA, taken up by naturally competent recipients that then recombine it into their chromosome to gain a new phenotype. Because the filtrate has no intact cells and no virus particles, the mechanisms that require those vectors are ruled out. (Choice A) Conjugation is wrong because it requires direct cell-to-cell contact: it is the "Transfer of DNA through direct contact using a conjugation pilus" (lines ~19649-19651), and a cell-free filtrate contains no living donor cells to extend a pilus. (Choice B) Transduction is wrong because it is the "Mechanism of horizontal gene transfer in bacteria in which genes are transferred through viral infection" (lines ~19652-19654); the filtrate is specified to contain no viral particles, so no bacteriophage vector is present. (Choice C) is correct: transformation is the "Mechanism of horizontal gene transfer in which naked environmental DNA is taken up by a bacterial cell" (lines ~19655-19657), matching the uptake of free DNA from the medium. (Choice D) Spontaneous mutation is wrong because resistance here is supplied by external DNA from the lysed donor, not generated de novo within the recipient; the source of the new sequence is the environmental DNA, consistent with transformation. This is a Knowledge of Scientific Concepts and Principles question because you must recall that uptake of naked DNA released by lysed cells defines transformation and distinguish it from the vector-dependent mechanisms of conjugation and transduction.$ex78$,
    'easy', '2B', $cc78$Prokaryotes and Viruses (BIO)$cc78$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a78A$Attributes the trait to conjugation, ignoring that a cell-free filtrate contains no donor cell to form a pilus bridge$a78A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a78B$Invokes a real HGT mechanism (transduction) but overlooks that the filtrate has no bacteriophage vector$a78B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a78D$Treats resistance as arising de novo by random mutation, ignoring that the resistance DNA was supplied externally$a78D$ FROM q;

-- Q12 [Prokaryotic Genetics: Transformation · medium · Skill 2 · ans D] (g79)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Transformation',
    $qt79$A graduate student grows a streptomycin-resistant donor strain and a streptomycin-sensitive recipient strain in the two halves of a U-tube separated by a fine filter that permits free passage of dissolved DNA but blocks any cell from crossing. The medium is confirmed phage-free, yet over several days streptomycin-resistant recipient colonies appear. Which mechanism MOST likely accounts for the resistance gene reaching the recipient cells?$qt79$,
    $op79$[{"label":"A","text":"Conjugation, in which the donor extends a pilus that draws the cells together and passes plasmid DNA through a cytoplasmic bridge"},{"label":"B","text":"Generalized transduction, in which a bacteriophage accidentally packages donor chromosomal DNA and injects it into a recipient"},{"label":"C","text":"Transposition, in which a mobile genetic element excises from the donor chromosome and inserts directly into the recipient chromosome"},{"label":"D","text":"Transformation, in which the recipient takes up naked DNA released into the medium and recombines it into its genome"}]$op79$::jsonb,
    'D',
    $ex79$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because the only horizontal gene transfer mechanism that requires neither cell-to-cell contact nor a viral vector is transformation, the uptake of free DNA from the environment. The filter blocks every cell from crossing, so any process needing physical contact is ruled out, and the medium is phage-free, so any process needing a bacteriophage is ruled out; the text states that "in transformation, the prokaryote takes up naked DNA found in its environment and that is derived from other cells that have lysed on death and released their contents, including their genome, into the environment," and that competent cells "actively bind to environmental DNA, transport it across their cell envelopes into their cytoplasm" (lines 19400-19403). Because only purified, dissolved DNA can cross the filter, that DNA carries the resistance allele to the recipient, which recombines it into its genome (line 19405-19406). (Choice A) Conjugation is incorrect: the text says "DNA is directly transferred from one prokaryote to another by means of a conjugation pilus, which brings the organisms into contact" (lines 19495-19496), but the filter prevents the cells from ever touching. (Choice B) Generalized transduction is incorrect because it requires a viral vector: "Viruses that infect bacteria (bacteriophages) may also move short pieces of chromosomal DNA from one bacterium to another in a process called transduction" (lines 19432-19433), yet the medium is confirmed phage-free. (Choice C) Transposition moves an element within or between DNA molecules inside a cell, not across an open medium between separated cells, so it cannot deliver the gene across the filter. (Choice D) is correct because transformation is the lone mechanism summarized as "naked DNA is taken up from the environment" (line 19372), needing no contact and no phage. This is a Scientific Reasoning and Problem Solving question because you must integrate the two experimental constraints—no cell contact and no phage—to eliminate conjugation, transduction, and transposition and identify transformation as the only viable route.$ex79$,
    'medium', '2B', $cc79$Prokaryotes and Viruses (BIO)$cc79$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a79A$Names a real HGT mechanism (conjugation) but ignores that the filter blocks the cell contact it requires$a79A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a79B$Names a real HGT mechanism (transduction) but ignores the explicit phage-free condition$a79B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a79C$Treats transposons as a cell-to-cell transfer route rather than an intracellular mobile element$a79C$ FROM q;

-- Q13 [Prokaryotic Genetics: Transposons · hard · Skill 2 · ans C] (g86)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Prokaryotic Genetics: Transposons',
    $qt86$A nonreplicative transposon excises from a plasmid and inserts squarely in the middle of the coding sequence of *hisB*, the chromosomal gene whose enzyme an *E. coli* strain requires to synthesize histidine. The cell's own promoter and ribosome-binding site for *hisB* remain intact. Which outcome is the MOST likely result of this insertion event?$qt86$,
    $op86$[{"label":"A","text":"The cell still synthesizes histidine normally, because the transposon copied itself and left the original hisB sequence undisturbed at its locus."},{"label":"B","text":"The cell synthesizes a HisB enzyme with a single altered amino acid, so histidine production is mildly reduced but not abolished."},{"label":"C","text":"The cell becomes a histidine auxotroph, because the inserted DNA interrupts the hisB reading frame and no functional HisB enzyme is produced."},{"label":"D","text":"The cell stops transcribing hisB entirely, because the transposon replaced the gene's promoter even though the coding sequence is undamaged."}]$op86$::jsonb,
    'C',
    $ex86$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is C because a transposon physically inserts a block of DNA into the middle of the *hisB* coding sequence, interrupting the reading frame so the ribosome can no longer translate a complete, functional HisB enzyme; without that enzyme the cell cannot make histidine and is a histidine auxotroph. OpenStax explains that transposons "independently excise from one location in a DNA molecule and integrate into the DNA elsewhere" and that "Movement within the same DNA molecule can alter phenotype by inactivating or activating a gene" (Ch.11, ~line 19601 and ~line 19609). Figure 11.31 illustrates exactly this mechanism: "a nonreplicative transposon has disrupted gene B. The consequence of that the transcription of gene B may now have been interrupted" (~line 19620). Because the disruption is the physical presence of inserted DNA inside the coding sequence — not a single nucleotide swap and not a change to an intact promoter — the result is complete loss of HisB function (insertional inactivation), the defining transposon phenotype here. (Choice A) is wrong because the prompt specifies a nonreplicative transposon, which moves in a "cut-and-paste" fashion (~line 19605), so the original locus is vacated and interrupted, not left intact; the "copy and paste" replicative behavior would still leave a disrupted copy at the insertion site regardless. (Choice B) describes a single point (missense) mutation altering one amino acid — a different mutational mechanism that does not apply, since a transposon inserts a large segment of DNA rather than swapping one base pair, and it shifts/breaks the reading frame instead of producing one substituted residue. (Choice C) is correct: insertional inactivation of the coding sequence destroys the reading frame and yields no functional enzyme, producing histidine auxotrophy. (Choice D) misattributes the effect to a regulatory (promoter) change; the stem states the *hisB* promoter and ribosome-binding site are intact, and the transposon landed inside the coding sequence, so transcription can still initiate but produces a disrupted, untranslatable message — the lesion is structural, not regulatory. This is a Scientific Reasoning and Problem Solving question because you must trace a specific molecular event (transposon insertion into a coding sequence) through to its enzymatic and whole-cell phenotypic consequence and distinguish that mechanism from point mutation and promoter disruption.$ex86$,
    'hard', '2B', $cc86$Prokaryotes and Viruses (BIO)$cc86$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a86A$Believing all transposons are replicative/copy-and-paste so the source gene is preserved, ignoring the stated nonreplicative cut-and-paste mode$a86A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a86B$Confusing transposon insertion (a large DNA block disrupting the reading frame) with a single base-pair point/missense mutation altering one amino acid$a86B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a86D$Attributing the loss of function to a promoter/regulatory disruption when the lesion is physical insertion within the intact-promoter coding sequence$a86D$ FROM q;

-- Q14 [Viral Genomes and Replication Strategy · easy · Skill 1 · ans D] (g91)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Viral Genomes and Replication Strategy',
    $qt91$A botanist purifies the bare RNA genome from a newly characterized plant virus and adds it, with no other viral components, to a cell-free extract containing only host ribosomes, tRNAs, amino acids, and ATP. Viral protein is produced immediately, before any nucleic-acid-copying enzyme acts on the genome. This result most directly indicates that the genome is:$qt91$,
    $op91$[{"label":"A","text":"negative-sense single-stranded RNA, which the ribosomes read only after it is copied into a complementary strand"},{"label":"B","text":"double-stranded RNA, whose negative strand is first transcribed by a viral RNA-dependent RNA polymerase"},{"label":"C","text":"single-stranded RNA that must first be reverse-transcribed into DNA before any viral protein can be made"},{"label":"D","text":"positive-sense single-stranded RNA, which acts directly as messenger RNA for the host ribosomes"}]$op91$::jsonb,
    'D',
    $ex91$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is D because only a positive-sense single-stranded RNA genome can be read straight off by host ribosomes the moment it enters, with no prior enzymatic copying. The text states that "If a virus has a +ssRNA genome, it can be translated directly to make viral proteins. Viral genomic +ssRNA acts like cellular mRNA" (lines 10344-10345), and it notes that most plant viruses "have a +ssRNA genome, which acts like messenger RNA (mRNA)" (lines 10449-10450). Because viral protein appears with no intervening copying step, the genome must already be in the message (positive) sense; any genome requiring an enzyme to first generate a readable strand is ruled out by the observation. (Choice A) Incorrect: a negative-sense genome "the host ribosomes cannot translate it until the −ssRNA is replicated into +ssRNA by viral RNA-dependent RNA polymerase" (lines 10346-10347), so it could not be translated directly. (Choice B) Incorrect: a dsRNA genome also depends on the viral RdRP, which "uses the negative strand of the double-stranded genome as a template to create +ssRNA" before any translation (lines 10348-10350). (Choice C) Incorrect: this describes retroviruses, which "carry a special enzyme called reverse transcriptase... synthesizes a complementary ssDNA (cDNA) copy" (lines 10365-10366); that DNA-intermediate step is an enzymatic copying step, which the experiment shows did not occur. (Choice D) Correct: a +ssRNA genome "can be translated directly" and "acts like cellular mRNA," exactly matching immediate protein production without copying. This is a Knowledge of Scientific Concepts and Principles question because you must recall that positive-sense RNA serves directly as mRNA while negative-sense, double-stranded, and reverse-transcribing genomes each require an enzymatic copying step before translation.$ex91$,
    'easy', '2B', $cc91$Prokaryotes and Viruses (BIO)$cc91$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a91A$Swaps the polarity rule — treats negative-sense RNA as if it were directly translatable, reversing which strand acts as mRNA$a91A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a91B$Names a real RNA genome type (dsRNA) that genuinely needs RdRP first, ignoring that the experiment showed no copying step$a91B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a91C$Imports the retrovirus reverse-transcription step into a non-retroviral RNA genome, inserting a DNA intermediate that did not occur$a91C$ FROM q;

-- Q15 [Viral Genomes and Replication Strategy · medium · Skill 2 · ans A] (g92)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Viral Genomes and Replication Strategy',
    $qt92$A virologist purifies the naked genomic RNA from a rabies-like \((-)\)sense single-stranded RNA virus and transfects it into susceptible cells, but no infection results; transfecting the same RNA from a \((+)\)sense ssRNA virus does start an infection, and intact \((-)\)sense virions are also fully infectious. Which feature of the intact \((-)\)sense virion explains why it CAN begin infection when its naked genome alone CANNOT?$qt92$,
    $op92$[{"label":"A","text":"The virion packages an RNA-dependent RNA polymerase that first copies the \\((-)\\)sense genome into a translatable \\((+)\\)sense strand."},{"label":"B","text":"The virion packages reverse transcriptase that copies the genome into DNA, which host enzymes then transcribe into translatable mRNA."},{"label":"C","text":"The virion's capsid proteins enter with the genome and are read directly by host ribosomes to launch viral protein synthesis."},{"label":"D","text":"The virion's envelope glycoproteins allow the \\((-)\\)sense genome to be translated directly once it reaches the cytoplasm."}]$op92$::jsonb,
    'A',
    $ex92$This is a Biology question that falls under the content category 'Prokaryotes and Viruses (BIO)'. The answer is A because a \((-)\)sense ssRNA genome cannot be read by host ribosomes, so the virus must bring its own enzyme to convert the genome into a translatable \((+)\)sense strand before any viral protein can be made. The textbook states that "if a virus contains a −ssRNA genome, the host ribosomes cannot translate it until the −ssRNA is replicated into +ssRNA by viral RNA-dependent RNA polymerase (RdRP)... The RdRP is brought in by the virus" (microbiology, lines 10345-10348). Naked \((-)\)sense RNA is therefore inert because no host enzyme can read it or copy it, but the intact virion carries the RdRP inside the particle, so it can immediately make the first \((+)\)strands. A \((+)\)sense genome needs no packaged enzyme because it "can be translated directly to make viral proteins" and "acts like cellular mRNA" (lines 10344-10345), which is why its naked RNA is infectious. (Choice A) Correct: the packaged RNA-dependent RNA polymerase generates the \((+)\)sense strand the ribosomes require. (Choice B) Reverse transcriptase is carried by retroviruses, which are "+ssRNA viruses... [that] carry a special enzyme called reverse transcriptase" making DNA (lines 10364-10366); a \((-)\)sense rabies-like virus does not use this RNA-to-DNA route, so this is the wrong enzyme and pathway. (Choice C) Capsid proteins are structural and are not templates for translation; only the nucleic acid genome can be read, and a \((-)\)sense strand still cannot be read directly. (Choice D) Envelope glycoproteins mediate attachment and entry, not translation; the sense of the genome, not the envelope, determines whether ribosomes can read it. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that ribosomes read only \((+)\)sense RNA to infer which enzyme a \((-)\)sense virion must carry to overcome a non-infectious naked genome.$ex92$,
    'medium', '2B', $cc92$Prokaryotes and Viruses (BIO)$cc92$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
