UNION ALL SELECT id, 'B', 'partial_truth', $a90B$Sheath is retained so original host is still infectable — true that the sheath is unchanged, but host range is set by fibers, not the sheath$a90B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a90D$Attaches but cannot inject because fibers drive penetration — assigns the sheath's injection role to the tail fibers$a90D$ FROM q;

